// The security headers of the site, in one place. Three consumers read this module, so they can never drift apart:
//   - nginx/security-headers.conf, generated by scripts/generate-security-headers.mjs and included by nginx.conf;
//   - `vite preview` (vite.config.ts), so every Playwright run executes under the real policy;
//   - the GitHub Pages build, which cannot send headers and gets the policy as a <meta> tag instead.
//
// The origins below are the ONLY external hosts the built site contacts. Fonts, brand files, project images and
// client logos are self hosted. Everything else is a link the visitor clicks (wa.me, LinkedIn, GitHub, Instagram):
// navigation is not governed by this policy.

import { BLOG_IMG_SRC } from './blogImageHosts.mjs';

/** The two lead webhooks (src/lib/contact.ts). The only POST the site makes. */
export const N8N_ORIGIN = 'https://n8n.vnone.com.br';
/** The blog reads the Supabase edge function first (src/utils/newsService.ts), then these two public feeds. */
export const BLOG_FEED_ORIGINS = Object.freeze([
  'https://qpcwoioflaxiasmcdfbd.supabase.co',
  'https://dev.to',
  'https://www.tabnews.com.br',
]);

/**
 * Directive name to its sources. A directive with no source (an empty array) is written as the bare keyword.
 *
 * style-src needs 'unsafe-inline': Radix Dialog (react-remove-scroll, style-singleton) and motion create style
 * elements at run time. React's own style props go through the CSSOM, which the policy allows.
 * img-src is 'self' plus BLOG_IMG_SRC (config/blogImageHosts.mjs): the five https hosts a blog cover image may come from
 * (src/utils/newsSanitize.ts refuses any other host before it is rendered) and data: for the inline SVG placeholder of
 * BlogPage.tsx. There is no bare `https:`. The home and the project pages only load 'self' images.
 * gnews.io is not allowed: the direct GNews call needs a key that must never be in the bundle (finding F-15).
 */
export const CSP_DIRECTIVES = Object.freeze({
  'default-src': ["'self'"],
  'script-src': ["'self'"],
  'style-src': ["'self'", "'unsafe-inline'"],
  'img-src': ["'self'", ...BLOG_IMG_SRC],
  'font-src': ["'self'"],
  'connect-src': ["'self'", N8N_ORIGIN, ...BLOG_FEED_ORIGINS],
  'object-src': ["'none'"],
  'base-uri': ["'self'"],
  'form-action': ["'self'"],
  'frame-ancestors': ["'none'"],
  'frame-src': ["'none'"],
  'manifest-src': ["'self'"],
  'upgrade-insecure-requests': [],
});

/** Directives a <meta http-equiv> policy ignores (and Chrome reports as an error): they only work in a header. */
const HEADER_ONLY_DIRECTIVES = Object.freeze(['frame-ancestors']);

/** The policy text for a directive map: `name source source; name; ...`. */
export function renderCsp(directives) {
  return Object.entries(directives)
    .map(([name, sources]) => [name, ...sources].join(' '))
    .join('; ');
}

export const CONTENT_SECURITY_POLICY = renderCsp(CSP_DIRECTIVES);

/** The policy of the GitHub Pages build: the same one, without the directives a meta tag cannot carry. */
export const META_CONTENT_SECURITY_POLICY = renderCsp(
  Object.fromEntries(Object.entries(CSP_DIRECTIVES).filter(([name]) => !HEADER_ONLY_DIRECTIVES.includes(name))),
);

/**
 * Strict-Transport-Security. NOT in SECURITY_HEADERS: it is only valid where TLS ends. The Docker image listens on
 * plain port 80 behind a proxy, so HSTS belongs on that proxy; it stays here as the documented value, and the nginx
 * snippet carries it commented out (owner decision O-S4). Without `preload`, so it can be undone.
 */
export const HSTS_VALUE = 'max-age=31536000; includeSubDomains';

/** Header name to value, sent on every response of the Docker image and of `vite preview`. */
export const SECURITY_HEADERS = Object.freeze({
  'Content-Security-Policy': CONTENT_SECURITY_POLICY,
  'X-Frame-Options': 'DENY',
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=()',
  'Cross-Origin-Opener-Policy': 'same-origin',
});

/** The `<meta>` tag of the GitHub Pages build. */
export function cspMetaTag() {
  return `<meta http-equiv="Content-Security-Policy" content="${META_CONTENT_SECURITY_POLICY}" />`;
}

const CHARSET_META = /<meta\s+charset="[^"]*"\s*\/?>/i;

/**
 * Puts the CSP meta tag right after the charset declaration (which must stay within the first 1024 bytes of the
 * page), or first in <head> when there is none, so the policy governs everything that follows.
 */
export function injectCspMeta(html) {
  const charset = CHARSET_META.exec(html);
  if (charset) {
    const end = charset.index + charset[0].length;
    return `${html.slice(0, end)}
    ${cspMetaTag()}${html.slice(end)}`;
  }
  if (!html.includes('<head>')) throw new Error('injectCspMeta: the page has no <head> to put the policy in');
  return html.replace('<head>', `<head>
    ${cspMetaTag()}`);
}

/**
 * The text of nginx/security-headers.conf. Each header is `always`, so it is also sent on 4xx and 5xx answers, and the
 * file is included in the server block and in EVERY location: nginx drops the add_header of an outer block as soon as
 * an inner block defines its own.
 */
export function renderNginxSnippet() {
  const lines = Object.entries(SECURITY_HEADERS).map(([name, value]) => `add_header ${name} "${value}" always;`);
  return [
    '# Generated by scripts/generate-security-headers.mjs from config/securityHeaders.mjs. Do not edit by hand:',
    '# change the module and run `npm run headers`.',
    '#',
    '# Include this file in the server block and in every location, because nginx does not inherit add_header',
    '# into a block that has its own add_header.',
    '#',
    '# Strict-Transport-Security is deliberately off: this container speaks plain HTTP behind a proxy, and HSTS must',
    '# be sent where TLS ends. Put it on that proxy, or uncomment the line if the proxy forwards X-Forwarded-Proto:',
    `# add_header Strict-Transport-Security "${HSTS_VALUE}" always;`,
    '',
    ...lines,
    '',
  ].join('\n');
}
